using System;using System.IO;using System.Linq;using System.Text;using System.ComponentModel;using System.Collections.Generic;using System.Globalization;using System.Runtime.Serialization;using System.Runtime.Serialization.Json;using System.Security.Cryptography;
namespace CircuitoStudio {
[DataContract]public enum CoordinationKind{[EnumMember] Selectivity,[EnumMember] Backup}
[DataContract]public enum CoordinationBasis{[EnumMember] ManufacturerTable,[EnumMember] TestReport}
[DataContract]public sealed class CoordinationRecord {
[DataMember]public CoordinationKind Kind{get;set;}[DataMember]public string UpstreamReference{get;set;}[DataMember]public string DownstreamReference{get;set;}[DataMember]public string UpstreamConfiguration{get;set;}[DataMember]public string DownstreamConfiguration{get;set;}[DataMember]public double SystemVoltageV{get;set;}[DataMember]public double FrequencyHz{get;set;}[DataMember]public double MinimumCurrentA{get;set;}[DataMember]public double LimitKA{get;set;}[DataMember]public CoordinationBasis Basis{get;set;}[DataMember]public string Issuer{get;set;}[DataMember]public string Document{get;set;}[DataMember]public string Page{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Scope{get;set;}
public CoordinationRecord(){UpstreamReference=DownstreamReference=UpstreamConfiguration=DownstreamConfiguration=Issuer=Document=Page=DataVersion=Scope="";}
public CoordinationRecord Copy(){return (CoordinationRecord)MemberwiseClone();}
public void Validate(){foreach(string value in new[]{UpstreamReference,DownstreamReference,Issuer,Document,Page,DataVersion,Scope})if(String.IsNullOrWhiteSpace(value)||value.Length>2000||value.IndexOf('\0')>=0)throw new InvalidDataException("Evidência exige referências, emissor, documento, página, versão e alcance (até 2000 caracteres).");foreach(string value in new[]{UpstreamConfiguration,DownstreamConfiguration})if(value==null||value.Length!=64||value.Any(x=>!Uri.IsHexDigit(x)))throw new InvalidDataException("Configuração do par inválida; exporte um modelo do par atual.");if(!Enum.IsDefined(typeof(CoordinationKind),Kind)||!Enum.IsDefined(typeof(CoordinationBasis),Basis))throw new InvalidDataException("Tipo/base da evidência inválidos.");Project.Range(SystemVoltageV,1,1e6,"tensão do par");Project.Range(FrequencyHz,1,1000,"frequência do par");Project.Range(LimitKA,.001,1e9,"limite do par");Project.Range(MinimumCurrentA,0,LimitKA*1000,"corrente mínima do alcance");}
}
[DataContract]public sealed class CoordinationBinding {
[DataMember]public string Engine{get;set;}[DataMember]public string UpstreamCircuitId{get;set;}[DataMember]public string DownstreamCircuitId{get;set;}[DataMember]public CoordinationRecord Record{get;set;}
public void Validate(){if(Engine!=Coordination.EngineId||Record==null||String.IsNullOrWhiteSpace(UpstreamCircuitId)||String.IsNullOrWhiteSpace(DownstreamCircuitId))throw new InvalidDataException("Vínculo de coordenação incompleto ou revisão desconhecida.");Project.Text(UpstreamCircuitId,"circuito montante",true);Project.Text(DownstreamCircuitId,"circuito jusante",true);Record.Validate();}
}
public sealed partial class Circuit{[DataMember(Order=96),Browsable(false)]public CoordinationBinding SelectivityEvidence{get;set;}[DataMember(Order=97),Browsable(false)]public CoordinationBinding BackupEvidence{get;set;}}
[DataContract]sealed class DeviceConfiguration {
[DataMember]public BreakerSnapshot Device;[DataMember]public double In,I2,MagneticA,Time,Energy,Rcd;[DataMember]public CurveStudyData Curves;
}
public sealed class CoordinationEvaluation{public string Status,Detail;public bool ContextMatches;public double? CurrentKA;}
public static class Coordination {
public const string EngineId="cs-coordenacao-tabelas-v1";
public const string Header="Kind;UpstreamReference;DownstreamReference;UpstreamConfiguration;DownstreamConfiguration;SystemVoltageV;FrequencyHz;MinimumCurrentA;LimitKA;Basis;Issuer;Document;Page;DataVersion;Scope";
public static Circuit Upstream(Project p,Circuit downstream){var board=p.Boards.SingleOrDefault(x=>x.Circuits.Contains(downstream));if(board==null)throw new InvalidDataException("Circuito fora do projeto.");return p.Boards.SelectMany(x=>x.Circuits).SingleOrDefault(x=>x.ChildBoardId==board.Id);}
public static string BaseConfiguration(Circuit circuit){if(circuit==null||circuit.Protection.BreakerSnapshot==null)return "";BreakerSelection.Validate(circuit);var pr=circuit.Protection;var context=new DeviceConfiguration{Device=pr.BreakerSnapshot,In=circuit.BreakerA,I2=pr.ConventionalTripA,MagneticA=pr.MagneticTripA,Time=pr.DisconnectSeconds,Energy=pr.LetThroughA2s,Rcd=pr.RcdMilliA,Curves=circuit.CurveStudy};using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(DeviceConfiguration)).WriteObject(stream,context);using(var hash=SHA256.Create())return String.Concat(hash.ComputeHash(stream.ToArray()).Select(x=>x.ToString("x2")));}}
public static string ProtectionConfiguration(Circuit circuit){string baseline=BaseConfiguration(circuit);return baseline==""||circuit.ProtectionResponses==null?baseline:ProtectionResponses.Hash(new[]{baseline,"protection-responses-v1",ProtectionResponses.Hash(circuit.ProtectionResponses)});}
public static string Configuration(Circuit circuit){string context=ProtectionConfiguration(circuit);if(context=="")return context;if(circuit.SwitchgearSelection!=null)context=ProtectionResponses.Hash(new[]{context,"switchgear-selection-v1",ProtectionResponses.Hash(circuit.SwitchgearSelection)});if(circuit.ResidualSelection!=null)context=ProtectionResponses.Hash(new[]{context,"residual-assemblies-v1",ProtectionResponses.Hash(circuit.ResidualSelection)});if(circuit.MotorStarterSelection!=null)context=ProtectionResponses.Hash(new[]{context,"motor-starter-assemblies-v1",ProtectionResponses.Hash(circuit.MotorStarterSelection)});return context;}

static string Reference(Circuit c){var r=c.Protection.BreakerSnapshot.Rating;return r.Manufacturer+" / "+r.Reference;}
public static CoordinationRecord Template(Project p,Circuit down,CoordinationKind kind){p.Validate();var up=Upstream(p,down);if(up==null||up.Protection.BreakerSnapshot==null||down.Protection.BreakerSnapshot==null)throw new InvalidDataException("O par automático exige alimentador do quadro e os dois disjuntores identificados por condição.");return new CoordinationRecord{Kind=kind,UpstreamReference=Reference(up),DownstreamReference=Reference(down),UpstreamConfiguration=Configuration(up),DownstreamConfiguration=Configuration(down),SystemVoltageV=p.Boards.Single(x=>x.Circuits.Contains(down)).Voltage,FrequencyHz=p.Frequency,LimitKA=1,Issuer="PREENCHER emissor da evidência",Document="PREENCHER documento",Page="PREENCHER página",DataVersion="PREENCHER versão",Scope="PREENCHER alcance e condições da associação"};}
public static CoordinationEvaluation Evaluate(Project p,Study study,Circuit down,CoordinationRecord record){var result=new CoordinationEvaluation{Status="Indeterminado",Detail="Sem evidência de associação do fabricante/ensaio; curvas individuais não comprovam seletividade nem backup."};if(record==null)return result;record.Validate();var up=Upstream(p,down);var dr=study.For(down);if(up==null||dr==null){result.Detail="Não existe proteção imediatamente a montante identificada pela ligação entre quadros.";return result;}var ur=study.For(up);result.CurrentKA=dr.FaultOriginKA;string detail="Motor "+EngineId+". Par automático: "+up.Id+" / "+down.Id+"; "+record.Kind+". Evidência declarada: "+record.Issuer+"; "+record.Document+", pág. "+record.Page+", versão "+record.DataVersion+"; "+record.Basis+". Alcance: "+record.Scope+". Faixa declarada "+record.MinimumCurrentA+" A até "+record.LimitKA+" kA; tensão "+record.SystemVoltageV+" V; "+record.FrequencyHz+" Hz. ";result.Detail=detail;
if(up.Protection.BreakerSnapshot==null||down.Protection.BreakerSnapshot==null){result.Detail+="Dispositivos sem identidade/condição vinculada; não inferir associação por correntes nominais.";return result;}
string nominal;bool contexts=BreakerSelection.Applicable(p,ur,up.Protection.BreakerSnapshot,out nominal)&&BreakerSelection.Applicable(p,dr,down.Protection.BreakerSnapshot,out nominal)&&record.SystemVoltageV==dr.Board.Voltage&&record.FrequencyHz==p.Frequency&&record.UpstreamReference==Reference(up)&&record.DownstreamReference==Reference(down)&&String.Equals(record.UpstreamConfiguration,Configuration(up),StringComparison.OrdinalIgnoreCase)&&String.Equals(record.DownstreamConfiguration,Configuration(down),StringComparison.OrdinalIgnoreCase);
if(!contexts){result.Detail+="Par, configurações, ajustes, curvas, tensão, frequência ou ligação não correspondem à evidência. Nenhuma extrapolação autorizada.";return result;}if(new[]{record.Issuer,record.Document,record.Page,record.DataVersion,record.Scope}.Any(x=>x.StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase))){result.Detail+="Modelo ainda não preenchido; não constitui evidência.";return result;}result.ContextMatches=true;
if(!ur.FaultOriginKA.HasValue||up.Protection.BreakingCapacityKA<ur.FaultOriginKA.Value){result.Detail+="Capacidade individual da proteção a montante não verificada/suficiente; não presumir associação adicional.";return result;}if(!dr.FaultOriginKA.HasValue){result.Detail+="Curto na origem do dispositivo a jusante indisponível.";return result;}double ik=dr.FaultOriginKA.Value;result.Detail+="Ik nominal 3F aproximado na origem a jusante="+ik.ToString("G8",CultureInfo.CurrentCulture)+" kA. ";if(ik*1000<record.MinimumCurrentA||ik>record.LimitKA){result.Detail+="Corrente fora do alcance declarado; não aprovar nem inferir comportamento fora da tabela.";return result;}
if(record.Kind==CoordinationKind.Selectivity&&down.Protection.BreakingCapacityKA<ik){result.Detail+="Capacidade individual a jusante insuficiente; validar separadamente eventual associação de backup antes de concluir o conjunto.";return result;}
result.Status="Compatível com tabela declarada";result.Detail+="A comparação nominal está dentro do alcance declarado para esse par/configuração exatos. Autenticidade e condições da evidência exigem conferência do responsável. Não prova Ik máximo normativo, outras faltas, seletividade fora da faixa ou adequação térmica/eletrodinâmica de todos os componentes. O teste individual de interrupção permanece separado; não aumenta fisicamente o Icu/Icn do dispositivo.";return result;}
public static CoordinationEvaluation EvaluateBinding(Project p,Study study,Circuit c,CoordinationKind kind){var bind=kind==CoordinationKind.Selectivity?c.SelectivityEvidence:c.BackupEvidence;if(bind==null)return Evaluate(p,study,c,null);bind.Validate();var up=Upstream(p,c);if(bind.Record.Kind!=kind||bind.DownstreamCircuitId!=c.Id||up==null||bind.UpstreamCircuitId!=up.Id)return new CoordinationEvaluation{Status="Indeterminado",Detail="Ligação/identidade de circuitos alterada desde o vínculo; reaplique a evidência para o par atual."};return Evaluate(p,study,c,bind.Record);}
public static void Attach(Project p,Circuit down,CoordinationRecord record){var study=Engineering.Analyze(p);var result=Evaluate(p,study,down,record);if(!result.ContextMatches)throw new InvalidDataException("Nenhuma alteração: evidência não corresponde ao par atual. "+result.Detail);var bind=new CoordinationBinding{Engine=EngineId,UpstreamCircuitId=Upstream(p,down).Id,DownstreamCircuitId=down.Id,Record=record.Copy()};if(record.Kind==CoordinationKind.Selectivity)down.SelectivityEvidence=bind;else down.BackupEvidence=bind;}
public static void Validate(Circuit c){if(c.SelectivityEvidence!=null){c.SelectivityEvidence.Validate();if(c.SelectivityEvidence.Record.Kind!=CoordinationKind.Selectivity)throw new InvalidDataException("Tipo incorreto no vínculo de seletividade.");}if(c.BackupEvidence!=null){c.BackupEvidence.Validate();if(c.BackupEvidence.Record.Kind!=CoordinationKind.Backup)throw new InvalidDataException("Tipo incorreto no vínculo de backup.");}}
static double Number(string text){double v;if(text.Contains('.')&&text.Contains(','))throw new InvalidDataException("Número ambíguo.");if(!Double.TryParse(text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out v)||Double.IsInfinity(v)||Double.IsNaN(v))throw new InvalidDataException("Número inválido.");return v;}
static T EnumValue<T>(string text){try{var x=(T)Enum.Parse(typeof(T),text,true);if(Enum.IsDefined(typeof(T),x))return x;}catch{}throw new InvalidDataException("Tipo de coordenação/base inválido.");}
static void ValidateRows(List<CoordinationRecord> rows){if(rows.Count>100000)throw new InvalidDataException("Tabela excede 100000 itens.");var keys=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var row in rows){if(row==null)throw new InvalidDataException("Linha ausente.");row.Validate();string key=row.Kind+"\0"+row.UpstreamConfiguration+"\0"+row.DownstreamConfiguration+"\0"+row.SystemVoltageV.ToString("R",CultureInfo.InvariantCulture)+"\0"+row.FrequencyHz.ToString("R",CultureInfo.InvariantCulture);if(!keys.Add(key))throw new InvalidDataException("Condição de par duplicada; consolide a fonte antes de importar.");}}
public static List<CoordinationRecord> Import(string file){if(new FileInfo(file).Length>32L*1024*1024)throw new InvalidDataException("Tabela excede 32 MiB.");var rows=CatalogData.Rows(File.ReadAllText(file,Encoding.UTF8).TrimStart('\uFEFF'));if(rows.Count==0||rows.Count>100001||String.Join(";",rows[0])!=Header)throw new InvalidDataException("Cabeçalho/tamanho incompatível.");var result=new List<CoordinationRecord>();for(int i=1;i<rows.Count;i++){try{var x=rows[i];if(x.Length!=15)throw new InvalidDataException("Esperadas 15 colunas.");result.Add(new CoordinationRecord{Kind=EnumValue<CoordinationKind>(x[0]),UpstreamReference=x[1],DownstreamReference=x[2],UpstreamConfiguration=x[3],DownstreamConfiguration=x[4],SystemVoltageV=Number(x[5]),FrequencyHz=Number(x[6]),MinimumCurrentA=Number(x[7]),LimitKA=Number(x[8]),Basis=EnumValue<CoordinationBasis>(x[9]),Issuer=x[10],Document=x[11],Page=x[12],DataVersion=x[13],Scope=x[14]});}catch(Exception ex){throw new InvalidDataException("Registro "+(i+1)+": "+ex.Message,ex);}}ValidateRows(result);return result;}
static string Quote(string x){return "\""+x.Replace("\"","\"\"")+"\"";}
public static void Export(IEnumerable<CoordinationRecord> rows,string file){var items=rows.ToList();ValidateRows(items);string full=Path.GetFullPath(file);Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{long bytes=3+Encoding.UTF8.GetByteCount(Header+"\r\n");using(var w=new StreamWriter(temp,false,new UTF8Encoding(true))){w.WriteLine(Header);foreach(var x in items){string line=String.Join(";",new[]{x.Kind.ToString(),x.UpstreamReference,x.DownstreamReference,x.UpstreamConfiguration,x.DownstreamConfiguration,x.SystemVoltageV.ToString("R",CultureInfo.InvariantCulture),x.FrequencyHz.ToString("R",CultureInfo.InvariantCulture),x.MinimumCurrentA.ToString("R",CultureInfo.InvariantCulture),x.LimitKA.ToString("R",CultureInfo.InvariantCulture),x.Basis.ToString(),x.Issuer,x.Document,x.Page,x.DataVersion,x.Scope}.Select(Quote));bytes+=Encoding.UTF8.GetByteCount(line+"\r\n");if(bytes>32L*1024*1024)throw new InvalidDataException("Tabela excede 32 MiB; destino preservado.");w.WriteLine(line);}}if(File.Exists(full))File.Replace(temp,full,full+".bak");else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
}
